// Projdeme všechny položky
for (const item of items) {
  // Pokud existují binární data v proměnné 'data'
  if (item.binary && item.binary.data) {
    // Ručně nastavíme typ na audio/ogg
    item.binary.data.mimeType = 'audio/ogg';
    // Pro jistotu nastavíme i příponu
    item.binary.data.fileExtension = 'oga';
    item.binary.data.fileName = 'voice_message.oga';
  }
}

return items;

